const fs = require('fs');
const path = require('path');

const kristenQuestions = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'generators', 'agama_kristen.json'), 'utf8'));
const seenQuestions = new Set(kristenQuestions.map(q => q.question));

function addQ(grade, difficulty, topic, question, options, correctAnswer, explanation) {
  if (seenQuestions.has(question)) {
    throw new Error(`Duplicate Kristen question found: "${question}"`);
  }
  seenQuestions.add(question);

  const diffCode = difficulty === 'mudah' ? 'm' : (difficulty === 'sedang' ? 's' : 'u');
  const index = kristenQuestions.filter(q => q.grade === grade && q.difficulty === difficulty).length + 1;
  const id = `aga-kristen-k${grade}-${diffCode}${String(index).padStart(2, '0')}`;

  kristenQuestions.push({
    id,
    grade,
    subject: 'pendidikan-agama',
    religion: 'kristen',
    difficulty,
    topic,
    question,
    options,
    correctAnswer,
    explanation
  });
}

addQ(5, 'mudah', 'Hari Paskah', 'Hari raya umat Kristen memperingati kebangkitan Tuhan Yesus Kristus dari kematian pada hari ketiga adalah ...', ['Natal', 'Paskah', 'Jumat Agung', 'Kenaikan'], 1, 'Paskah adalah hari kemenangan kebangkitan Kristus yang mengalahkan kuasa maut.');
addQ(5, 'mudah', 'Jumat Agung', 'Hari peringatan sengsara dan wafatnya Tuhan Yesus di kayu salib di bukit Golgota dinamakan hari ...', ['Jumat Agung', 'Kamis Putih', 'Sabtu Suci', 'Minggu Palma'], 0, 'Jumat Agung memperingati karya penebusan Kristus melalui pengorbanan salib.');
addQ(5, 'mudah', 'Kenaikan Yesus', 'Tuhan Yesus terangkat naik ke surga disaksikan oleh murid-murid-Nya setelah ... hari sejak kebangkitan-Nya.', ['10 hari', '40 hari', '50 hari', '100 hari'], 1, 'Kisah Para Rasul 1:3 mencatat Yesus menampakkan diri selama 40 hari sebelum naik ke surga.');
addQ(5, 'mudah', 'Hari Pentakosta', 'Hari Pentakosta yang dirayakan lima puluh hari setelah Paskah memperingati peristiwa ...', ['Kelahiran Yesus', 'Turunnya Roh Kudus kepada para rasul', 'Pembaptisan Yesus di Sungai Yordan', 'Pembangunan Bait Salomo'], 1, 'Pentakosta memperingati pencurahan Roh Kudus dan lahirnya Gereja perdana.');
addQ(5, 'mudah', 'Pertobatan Saulus', 'Tokoh yang dulunya menganiaya jemaat Kristen namun bertobat setelah melihat cahaya terang di jalan Damsyik bernama ...', ['Kaisar Nero', 'Saulus (kemudian menjadi Rasul Paulus)', 'Herodes', 'Pontius Pilatus'], 1, 'Saulus mengalami perjumpaan adikodrati dengan Kristus dan menjadi pemberita Injil terkemuka.');
addQ(5, 'mudah', 'Perumpamaan Anak Hilang', 'Perumpamaan Yesus tentang anak bungsu yang meminta harta warisan lalu menghabiskannya berfoya-foya di negeri jauh disebut ...', ['Perumpamaan Bendahara Tidak Jujur', 'Perumpamaan Anak yang Hilang', 'Perumpamaan Domba yang Hilang', 'Perumpamaan Dirham yang Hilang'], 1, 'Lukas 15 menceritakan kasih Bapa yang mengampuni anak yang terhilang.');
addQ(5, 'mudah', 'Sambut Bapa', 'Ketika melihat anak bungsu yang terhilang pulang dengan penuh penyesalan, tindakan sang ayah adalah ...', ['Mengusirnya karena hartanya habis', 'Berlari memeluk, mencium, dan memulihkan martabatnya dengan pesta sukacita', 'Menyuruhnya menjadi budak di kandang babi', 'Menuntut ganti rugi uang warisan'], 1, 'Sang ayah berlari menyambut dengan belas kasih dan menyelenggarakan perjamuan sukacita.');
addQ(5, 'mudah', 'Sikap Saudara Sulung', 'Saudara sulung dalam perumpamaan Anak yang Hilang menunjukkan sikap ...', ['Ikut menari gembira', 'Marah, iri hati, dan menolak masuk ke dalam rumah pesta', 'Membelikan baju baru untuk adiknya', 'Mendoakan adiknya di kamar'], 1, 'Anak sulung merasa iri dan mengungkit kepatuhannya, cerminan sikap legalistik orang Farisi.');
addQ(5, 'mudah', 'Perumpamaan Talenta', 'Tuhan Yesus mengajarkan bahwa kemampuan dan bakat (talenta) yang diberikan Tuhan kepada kita harus ...', ['Disimpan di dalam tanah agar aman', 'Dikembangkan dan digunakan dengan tekun untuk kemuliaan Tuhan dan sesama', 'Dibiarkan menganggur', 'Dijual kepada orang lain'], 1, 'Matius 25: talenta harus dikembangkan secara bertanggung jawab.');
addQ(5, 'mudah', 'Kejujuran Pelajar', 'Mengerjakan ulangan sekolah dengan jujur tanpa mencontek merupakan perwujudan karakter ...', ['Anak yang malas', 'Murid Kristus yang berintegritas', 'Orang yang sombong', 'Murid yang kuper'], 1, 'Kejujuran akademik adalah bukti kesalehan hidup di hadapan Tuhan.');

addQ(5, 'sedang', 'Jalan Damsyik', 'Ketika Saulus rebah ke tanah di jalan menuju Damsyik, suara dari surga berkata kepadanya: ...', ['"Saulus, Saulus, mengapa engkau menganiaya Aku?"', '"Saulus, pulanglah ke Yerusalem sekarang juga"', '"Saulus, bangunlah benteng perang baru"', '"Saulus, kejarlah para rasul itu"'], 0, 'Kisah Para Rasul 9:4: Yesus mengidentifikasikan diri-Nya dengan jemaat yang dianiaya Saulus.');
addQ(5, 'sedang', 'Ananias Menyembuhkan', 'Murid Tuhan di Damsyik yang diutus Roh Kudus menumpangkan tangan menyembuhkan kebutaan Saulus bernama ...', ['Kornelius', 'Ananias', 'Barnabas', 'Silas'], 1, 'Ananias taat menyambut Saulus sebagai saudara seiman di dalam Tuhan.');
addQ(5, 'sedang', 'Hamba Lima Talenta', 'Hamba yang menerima lima talenta dan dua talenta mendapat pujian dari tuannya karena berhasil ...', ['Menyembunyikan uang di gua batu', 'Memperdagangkan dan melipatgandakan keuntungan talentanya menjadi dua kali lipat', 'Membelanjakannya untuk pesta pora', 'Meminjamkannya dengan bunga mencekik'], 1, 'Hamba yang setia membuahkan hasil berlipat ganda dipuji sebagai hamba yang baik dan setia.');
addQ(5, 'sedang', 'Hamba Satu Talenta', 'Hamba yang menerima satu talenta dicap sebagai hamba yang jahat dan malas karena ia ...', ['Merampok hamba lain', 'Menggali tanah dan mengubur talenta tuannya karena takut dan curiga', 'Menghilangkan uang di pasar', 'Membeli tanah gandum'], 1, 'Hamba tersebut malas dan berprasangka buruk terhadap tuannya sehingga menyia-nyiakan kepercayaan.');
addQ(5, 'sedang', 'Makna Penebusan Salib', 'Pengorbanan Kristus di kayu salib menebus orang percaya dari ...', ['Kewajiban bekerja mencari nafkah', 'Kutuk dosa dan belenggu maut kekal', 'Tuntutan hukum lalu lintas', 'Penyakit flu biasa'], 1, 'Yesus menanggung hukuman dosa manusia di kayu salib agar setiap orang beroleh pengampunan dan hidup kekal.');
addQ(5, 'sedang', 'Makna Perjamuan Kudus', 'Roti yang dipecah-pecahkan dan anggur yang dituangkan dalam sakramen Perjamuan Kudus melambangkan ...', ['Makanan penutup makan malam', 'Tubuh Kristus yang terpecah dan darah Kristus yang tercurah bagi pengampunan dosa kita', 'Kekayaan rempah-rempah tanah Kanaan', 'Keberhasilan panen para petani'], 1, '1 Korintus 11:24-25 menegaskan roti dan anggur adalah peringatan akan tubuh dan darah Kristus.');
addQ(5, 'sedang', 'Jalan Kebenaran Hidup', 'Dalam Yohanes 14:6 Yesus bersabda: "Akulah ..., dan kebenaran dan hidup. Tidak ada seorang pun yang datang kepada Bapa, kalau tidak melalui Aku".', ['Batu sandungan', 'Jalan', 'Pintu gerbang emas', 'Cahaya bulan'], 1, 'Yesus menegaskan diri-Nya sebagai satu-satunya jalan pendamaian antara manusia dan Allah Bapa.');
addQ(5, 'sedang', 'Menolak Membolos', 'Ketika kawan mengajak kita membolos sekolah pada jam pelajaran agama, sikap tegas anak kristiani adalah ...', ['Ikut membolos agar tidak dijauhi geng', 'Menolak dengan tegas dan menasihati teman agar menghargai waktu belajar serta jerih payah orang tua', 'Meminta uang jajan tambahan sebelum ikut membolos', 'Bersembunyi di toilet sepanjang hari'], 1, 'Menolak ajakan salah membuktikan kematangan moral anak beriman.');
addQ(5, 'sedang', 'Toleransi Antar Agama', 'Menghormati tetangga yang berbeda keyakinan saat mereka menjalankan ibadah merupakan wujud nyata ...', ['Kelemahan iman pribadi', 'Toleransi beragama dan kerukunan hidup berbangsa', 'Pencampuran ajaran aqidah', 'Ketidakpedulian sosial'], 1, 'Toleransi sejati menghormati kebebasan beribadah sesama anak bangsa dalam bingkai kasih.');
addQ(5, 'sedang', 'Peran Roh Kudus Penghibur', 'Tuhan Yesus menjanjikan Roh Kudus sebagai "Penolong" (Parakletos) yang memiliki fungsi untuk ...', ['Menghukum manusia di muka umum', 'Menghibur, mengajar, dan menuntun orang percaya ke dalam segala kebenaran', 'Membuat manusia kebal dari rasa lapar', 'Menggantikan keberadaan firman Alkitab'], 1, 'Roh Kudus menginsafkan dunia akan dosa dan menuntun orang percaya hidup dalam kebenaran Kristus.');
addQ(5, 'sedang', 'Paulus Silas di Penjara', 'Ketika Paulus dan Silas dipenjarakan di Filipi dalam keadaan kaki terpasung, tengah malam mereka merespons penderitaan dengan cara ...', ['Mengutuk para sipir penjara', 'Berdoa dan menyanyikan puji-pujian kepada Allah hingga terdengar oleh para tahanan lain', 'Mogok makan dan menangis histeris', 'Mencoba mendobrak pintu besi penjara'], 1, 'Kisah Para Rasul 16:25: Sukacita iman dalam hadirat Tuhan mengatasi belenggu penjara fisik.');
addQ(5, 'sedang', 'Pertobatan Kepala Penjara', 'Setelah gempa bumi membuka pintu penjara dan Paulus mencegah kepala penjara bunuh diri, kepala penjara itu bersujud bertanya: ...', ['"Berapa harga jubah yang kalian pakai?"', '"Tuan-tuan, apakah yang harus aku perbuat, supaya aku selamat?"', '"Di mana kalian menyembunyikan kunci borgol?"', '"Siapa yang membayar kerusakan tembok ini?"'], 1, 'Kisah Para Rasul 16:30: Kesaksian hidup Paulus memimpin kepala penjara mencari keselamatan jiwa.');
addQ(5, 'sedang', 'Melayani Musik Gereja', 'Menggunakan talenta bermain piano atau gitar untuk mengiringi nyanyian jemaat di gereja dengan setia merupakan bentuk ...', ['Pamer kehebatan jari-jemari', 'Ibadah pelayanan mengembangkan talenta bagi kemuliaan nama Tuhan', 'Mencari bayaran uang saku', 'Menghabiskan waktu luang tanpa arah'], 1, 'Melayani Tuhan dengan talenta musik memperkaya persekutuan jemaat dalam menyembah Allah.');
addQ(5, 'sedang', 'Panggilan Turun Zakheus', 'Ketika Yesus memanggil Zakheus dari atas pohon ara, orang banyak bersungut-sungut karena mereka menganggap Zakheus sebagai orang ...', ['Sakit kusta', 'Berdosa', 'Kekurangan gizi', 'Paling suci di kota'], 1, 'Yesus datang mencari dan menyelamatkan yang terhilang, merangkul kaum marjinal yang dicap berdosa.');
addQ(5, 'sedang', 'Ciri Kasih Sejati', '1 Korintus 13:4-5 menyatakan bahwa kasih itu sabar dan murah hati; ia tidak cemburu, tidak memegahkan diri, dan tidak ...', ['Tersenyum saat senang', 'Mencari keuntungan diri sendiri dan tidak pemarah', 'Menyapa sahabat', 'Berbagi makanan bekal'], 1, 'Kasih sejati tidak egois; ia menolak kesombongan dan kemarahan yang melukai orang lain.');
addQ(5, 'sedang', 'Tiga Nilai Kekal', 'Dalam 1 Korintus 13:13, tiga kebajikan yang tinggal tetap adalah iman, pengharapan, dan kasih; dan yang paling besar di antaranya adalah ...', ['Iman', 'Kasih', 'Pengharapan', 'Keberanian perang'], 1, 'Kasih adalah yang terbesar karena kasih mencerminkan hakikat kekal dari karakter Allah sendiri.');
addQ(5, 'sedang', 'Tanda Pertobatan Sejati', 'Pertobatan sejati (metanoia) ditandai dengan perubahan nyata yaitu ...', ['Hanya menangis saat didoakan lalu mengulangi kesalahan yang sama', 'Pembaruan cara berpikir, berbalik dari jalan dosa, dan melangkah hidup menurut kehendak Tuhan', 'Membeli pakaian putih baru', 'Pindah tempat tinggal ke kota lain'], 1, 'Metanoia adalah pembalikan arah hidup secara mendasar dari kegelapan menuju terang kebenaran.');
addQ(5, 'sedang', 'Membantu Panti Asuhan', 'Memberikan sumbangan alat tulis dan seragam kepada anak-anak panti asuhan dengan tulus mencerminkan perintah Alkitab untuk ...', ['Mencari popularitas di koran lokal', 'Memperhatikan anak yatim piatu dalam kesusahan mereka sebagai ibadah murni', 'Membayar pajak penghasilan', 'Menghabiskan kelebihan barang bekas rumah'], 1, 'Yakobus 1:27: Ibadah yang murni dan tak bercacat di hadapan Allah Bapa adalah mengunjungi yatim piatu dan janda dalam kesusahan.');
addQ(5, 'sedang', 'Menolak Narkoba dan Pergaulan Bebas', 'Menolak bujukan teman untuk merokok, mencoba narkoba, atau menonton video terlarang merupakan wujud ketaatan menjaga ...', ['Uang jajan agar tidak berkurang', 'Kekudusan tubuh dan kehormatan hidup sebagai bait Allah', 'Waktu bermain game', 'Kerapian seragam sekolah'], 1, 'Menjaga kekudusan moral melindungi masa depan dan menghormati kekudusan bait Roh Kudus.');
addQ(5, 'sedang', 'Teladan Stefanus Mengampuni', 'Stefanus, martir kristiani pertama, saat dirajam batu oleh para penentangnya mengucapkan doa pemaafan yang meneladani Yesus yaitu: ...', ['"Turunkanlah api membakar mereka semua!"', '"Tuhan, janganlah tanggungkan dosa ini kepada mereka!"', '"Balaslah kejahatan mereka sepuluh kali lipat!"', '"Biarkan mereka menderita selamanya!"'], 1, 'Kisah Para Rasul 7:60: Stefanus mati dengan mendoakan pengampunan bagi para penganiayanya.');

addQ(5, 'sulit', 'Analisis Teologis Anak yang Hilang', 'Ketika anak bungsu pulang dengan rencana berkata "jadikanlah aku sebagai salah seorang upahanmu", mengapa sang ayah justru menyuruh pelayan memakaikan jubah terbaik, cincin pada jarinya, dan kasut pada kakinya?', ['Karena ayah ingin memamerkan kekayaannya kepada tetangga', 'Karena cincin dan kasut melambangkan pemulihan penuh status martabat anak yang merdeka, bukan budak upahan, membuktikan anugerah pembenaran cuma-cuma dari Allah', 'Karena baju anak itu terlalu sempit', 'Supaya anak itu segera dipekerjakan di ladang gandum'], 1, 'Jubah terbaik, cincin meterai, dan kasut adalah simbol restorasi penuh hak istimewa sebagai anak kandung yang dikasihi.');
addQ(5, 'sulit', 'Kritik Sikap Saudara Sulung', 'Mengapa sikap anak sulung yang menolak masuk ke rumah pesta perjumpaan adiknya dianggap oleh para penafsir Alkitab mencerminkan dosa yang lebih berbahaya daripada dosa anak bungsu?', ['Karena anak sulung tidak mau makan daging lembu tambun', 'Karena ia terjebak dalam kesalehan legalistik yang merasa diri suci, menyimpan kepahitan batin, dan tidak memiliki hati yang penuh belas kasih seperti Bapa', 'Karena anak sulung merusak perabot rumah', 'Hanya persoalan pembagian warisan yang belum selesai'], 1, 'Dosa kepahitan hati, merasa diri benar sendiri (self-righteousness), dan ketiadaan kasih meracuni jiwa dari dalam.');
addQ(5, 'sulit', 'Makna Transformasi Radikal Paulus', 'Transformasi Saulus dari seorang pembenci fanatik yang menganiaya murid Yesus menjadi Rasul Paulus yang rela menderita dicambuk dan dipenjara demi Injil membuktikan bahwa ...', ['Saulus ingin mencari jabatan politik baru di Roma', 'Kuasa anugerah Kristus yang hidup sanggup membongkar kepalsuan fanatisme agama dan memperbarui nurani manusia secara radikal', 'Saulus takut kepada tentara Romawi', 'Paulus tergiur oleh kekayaan persembahan jemaat'], 1, 'Pertobatan Paulus menjadi salah satu bukti historis paling kokoh atas kebangkitan Kristus dan kuasa Injil yang mengubah hidup.');
addQ(5, 'sulit', 'Bahaya Mengubur Talenta', 'Dalam Perumpamaan Talenta, mengapa hamba yang menerima satu talenta dihukum dengan dicampakkan ke dalam kegelapan? Pelajaran etis bagi kita adalah ...', ['Karena ia tidak mampu membeli lima talenta baru', 'Ketakutan, kemalasan, dan prasangka buruk terhadap Allah yang memicu manusia menyembunyikan potensinya adalah dosa ketidaksetiaan yang fatal', 'Karena tuannya sangat kikir dan kejam', 'Hanya perumpamaan cerita fiksi tanpa makna moral'], 1, 'Menyia-nyiakan anugerah Tuhan karena takut melangkah dan berprasangka salah terhadap karakter Tuhan adalah pengkhianatan amanah.');
addQ(5, 'sulit', 'Teologi Penebusan Salib Pengganti', 'Mengapa Alkitab mengajarkan bahwa keselamatan manusia semata-mata adalah "karena kasih karunia oleh iman" (sola gratia, sola fide) dan bukan karena usaha amal manusia?', ['Supaya manusia tidak perlu lagi berbuat baik kepada sesama', 'Karena tidak ada manusia berdosa yang mampu memenuhi tuntutan kesucian hukum Allah dengan kekuatannya sendiri; keselamatan adalah anugerah cuma-cuma melalui kurban pengganti Kristus', 'Karena beramal itu melelahkan fisik manusia', 'Hanya peraturan khusus bangsa Yahudi'], 1, 'Efesus 2:8-9 menegaskan keselamatan adalah hadiah anugerah Allah agar tidak ada orang yang memegahkan diri.');
addQ(5, 'sulit', 'Analisis Yohanes 15 Pokok Anggur', 'Yesus bersabda: "Akulah pokok anggur yang benar dan Kamulah ranting-rantingnya. Barangsiapa tinggal di dalam Aku dan Aku di dalam dia, ia berbuah banyak, sebab di luar Aku kamu ..."', ['Bisa berbuah sendiri di musim gugur', 'Tidak dapat berbuat apa-apa', 'Menjadi pohon yang paling besar', 'Akan segera menjadi kaya raya'], 1, 'Kunci kehidupan spiritual yang berbuah kebajikan sejati adalah persekutuan yang melekat erat dan terus-menerus dengan Kristus Sang Pokok Anggur.');
addQ(5, 'sulit', 'Integritas di Tengah Tekanan Suap', 'Jika seorang murid kristiani ditawari bocoran soal ujian oleh temannya dengan imbalan uang, sikap iman yang harus ditunjukkan adalah ...', ['Membeli bocoran soal tersebut demi menyelamatkan ranking kelas', 'Menolak secara tegas dan tidak terlibat dalam perbuatan curang karena takut akan TUHAN dan menjunjung tinggi kehormatan kejujuran', 'Membeli lalu membagikannya gratis ke teman-teman', 'Menyimpan soal itu di tas tanpa membacanya'], 1, 'Integritas kristiani menolak kompromi ketidakjujuran sekalipun menawarkan kemudahan duniawi semu.');
addQ(5, 'sulit', 'Tantangan Menghadapi Penderitaan Tanpa Salah', 'Ketika orang percaya menderita karena mempertahankan kebenaran dan keadilan, 1 Petrus 4:16 menasihatkan: "Janganlah ia malu, melainkan hendaklah ia ..."', ['Membalas dendam saat malam hari', 'Memuliakan Allah dalam nama Kristus itu', 'Menyerah dan meninggalkan imannya', 'Menuntut ganti rugi kepada pemerintah'], 1, 'Menderita karena kebenaran adalah bagian dari memikul salib Kristus yang mendatangkan kemuliaan ilahi.');
addQ(5, 'sulit', 'Makna "Bukan Milik Dunia Ini"', 'Yesus berdoa bagi murid-murid-Nya dalam Yohanes 17: "Aku tidak meminta, supaya Engkau mengambil mereka dari dunia, tetapi supaya Engkau melindungi mereka dari pada yang jahat. Mereka bukan dari dunia, sama seperti Aku bukan dari dunia". Maknanya bagi pelajar adalah ...', ['Menolak berbicara dengan orang yang belum percaya', 'Hidup berkarya di tengah masyarakat modern tanpa terpengaruh oleh arus moral dekadensi dan nilai-nilai kejahatan duniawi', 'Pindah tinggal ke biara di puncak bukit', 'Menolak menggunakan internet dan teknologi'], 1, 'Orang percaya dipanggil menjadi "in the world but not of the world" (berada di dunia tetapi tidak serupa dengan nilai-nilai fasik dunia).');
addQ(5, 'sulit', 'Analisis Perjamuan di Rumah Simon Kusta', 'Ketika Maria meminyaki kaki Yesus dengan minyak narwastu murni yang sangat mahal, Yudas Iskariot memprotes dengan dalih uangnya bisa dibagikan kepada orang miskin. Mengapa Yesus membela tindakan Maria?', ['Karena Yesus menyukai minyak wangi mahal', 'Karena Maria mempersembahkan penghormatan kasih pengorbanan terbaik untuk mempersiapkan penguburan Kristus, sementara Yudas bermotif serakah mencuri uang kas', 'Karena Maria adalah kerabat dekat para rasul', 'Supaya Simon kusta merasa senang'], 1, 'Yesus menghargai ungkapan kasih pengorbanan tulus yang mengenali waktu kairos karya penebusan Kristus.');
addQ(5, 'sulit', 'Menyikapi Sahabat yang Mengkhianati Rahasia', 'Bila sahabat karib kita membocorkan rahasia kelemahan pribadi kita ke seisi sekolah, teladan Kristus saat dikhianati ciuman Yudas di Getsemani mengajarkan kita untuk ...', ['Menyerang dan merusak reputasi keluarga sahabat tersebut', 'Mengendalikan amarah batin, mengikhlaskan perbuatan salahnya, dan menyerahkan keadilan kepada Tuhan tanpa membalas dendam', 'Membakar buku tugas sahabat tersebut', 'Berhenti bersekolah selamanya'], 1, 'Kristus merespons pengkhianatan dengan ketenangan kedaulatan ilahi, tidak membalas kejahatan dengan kekerasan.');
addQ(5, 'sulit', 'Filosofi Kasih Agapao Melampaui Perasaan', 'Kasih kristiani (agape) sering didefinisikan sebagai keputusan kehendak moral (act of will), bukan sekadar emosi atau perasaan sesaat. Artinya mengasihi sesama adalah ...', ['Hanya mau menolong saat suasana hati (mood) sedang gembira', 'Komitmen teguh untuk memperlakukan orang lain dengan kebaikan, keadilan, dan belas kasih tanpa peduli bagaimana perasaan kita terhadap orang itu', 'Menyetujui semua tindakan jahat orang lain', 'Mengharuskan kita membelikan hadiah mahal setiap hari'], 1, 'Kasih agape berlandaskan ketaatan moral dan komitmen ilahi untuk memberkati orang lain terlepas dari suka atau tidak suka.');
addQ(5, 'sulit', 'Kearifan Ayub Menanggapi Istrinya', 'Ketika tertimpa bencana hebat dan tubuhnya dipenuhi borok bernanah, istri Ayub berkata: "Kutukilah Allahmu dan matilah!". Ayub menjawab dengan penuh kebijaksanaan iman: ...', ['"Apakah kita hanya mau menerima yang baik dari Allah, tetapi tidak mau menerima yang buruk?"', '"Aku setuju dengan perkataanmu, mari kita tinggalkan Tuhan"', '"Pergilah membeli obat herbal ke negeri tetangga"', '"Aku akan mencari tuhan baru yang lebih kaya"'], 0, 'Ayub 2:10: Iman Ayub yang matang mengakui kedaulatan mutlak Allah baik di masa kelimpahan maupun di masa ujian penderitaan.');
addQ(5, 'sulit', 'Menghadapi Era Digital Tanpa Kehilangan Hati Nurani', 'Bagaimana seorang siswa kelas 5 membentengi nuraninya saat menyaksikan konten hoaks dan ujaran kebencian di media sosial?', ['Ikut menyebarkannya ke status WhatsApp kelas agar viral', 'Menguji kebenaran informasi dengan kritis (filing firman), tidak terpancing membagikan kabar bohong, dan memilih menyebarkan inspirasi kasih', 'Membuat ujaran kebencian tandingan dengan akun anonim', 'Menghancurkan gawai dengan palu'], 1, 'Kecerdasan digital kristiani memadukan hikmat kritis, integritas kebenaran, dan etika kasih dalam bermedia sosial.');
addQ(5, 'sulit', 'Analisis Panggilan Matius Pemungut Cukai', 'Ketika orang-orang Farisi mengecam Yesus makan bersama para pemungut cukai dan orang berdosa di rumah Matius, jawaban Yesus yang penuh kuasa adalah ...', ['"Aku datang hanya untuk beristirahat makan siang"', '"Bukan orang sehat yang memerlukan tabib, tetapi orang sakit. Aku datang bukan untuk memanggil orang benar, melainkan orang berdosa supaya bertobat"', '"Aku akan menyuruh mereka membayar pajak kepadaku"', '"Mereka adalah orang-orang yang paling kaya di kota Kapernaum"'], 1, 'Matius 9:12-13: Misi Kristus adalah penyelamatan jiwa-jiwa yang terluka dan terhilang dalam lumpur dosa.');
addQ(5, 'sulit', 'Konsep Kesatuan Tubuh Kristus', '1 Korintus 12 mengajarkan bahwa gereja adalah tubuh Kristus yang memiliki banyak anggota (tangan, kaki, mata, telinga). Pelajaran penting bagi kehidupan bersama adalah ...', ['Anggota yang tampak lemah tidak berguna sama sekali', 'Setiap anggota memiliki fungsi unik yang saling melengkapi dan tidak boleh saling meremehkan; jika satu anggota menderita, semua ikut menderita', 'Mata berhak mengusir kaki dari tubuh', 'Hanya anggota yang pandai berbicara yang dihargai'], 1, 'Kesatuan dalam keberagaman karunia: semua anggota tubuh memiliki nilai martabat sama dan saling bergantung dalam kasih.');
addQ(5, 'sulit', 'Makna "Memikul Salib Setiap Hari"', 'Yesus bersabda: "Setiap orang yang mau mengikut Aku, ia harus menyangkal dirinya, memikul salibnya setiap hari dan mengikut Aku" (Lukas 9:23). Memikul salib bagi seorang pelajar bermakna ...', ['Membawa kayu salib besar saat berjalan ke sekolah', 'Rela mengorbankan egoisme, menolak kenikmatan dosa, dan setia berpegang pada kebenaran Kristus sekalipun harus ditertawakan teman sebaya', 'Membiarkan diri dipukuli oleh orang lain tanpa membela diri', 'Menolak makan dan minum sepanjang hari'], 1, 'Memikul salib adalah kesediaan moral menundukkan ego pribadi dan setia mematuhi kehendak Allah di tengah tantangan zaman.');
addQ(5, 'sulit', 'Pengorbanan Martir Perdana Stefanus', 'Sebelum Stefanus menghembuskan nafas terakhir saat dirajam batu, ia menatap ke langit dan melihat ...', ['Hujan emas jatuh dari surga', 'Kemuliaan Allah dan Yesus berdiri di sebelah kanan Allah menyambut kedatangan hamba-Nya', 'Bala tentara malaikat bersenjata pedang api membalas dendam', 'Kota Yerusalem terbakar musnah'], 1, 'Kisah Para Rasul 7:55-56: Visi kemuliaan Kristus yang berdiri menyambut martir-Nya memberi kekuatan damai mengatasi kengerian maut.');
addQ(5, 'sulit', 'Tantangan Kemunafikan Ragi Orang Farisi', 'Yesus memperingatkan murid-murid-Nya: "Waspadalah terhadap ragi orang Farisi, yaitu kemunafikan". Bahaya kemunafikan dalam kehidupan beragama adalah ...', ['Membuat adonan roti menjadi terlalu mengembang', 'Mementingkan topeng pencitraan kesalehan lahiriah di depan orang banyak padahal hatinya penuh dengan kebusukan moral dan keserakahan', 'Mengurangi pendapatan kas bait suci', 'Hanya tradisi makan roti tanpa ragi saat Paskah'], 1, 'Kemunafikan membutakan nurani; ia menukar kemurnian iman di hadapan Allah dengan tepuk tangan sanjungan manusia yang semu.');
addQ(5, 'sulit', 'Pemberian Berkat Tanpa Balas Kasih', 'Amsal 25:21-22 menasihatkan: "Jikalau seterumu lapar, berilah dia makan roti, dan jikalau dia dahaga, berilah dia minum air... dan TUHAN akan membalasnya kepadamu". Apa tujuan spiritual dari tindakan ini?', ['Meracuni makanan lawan agar tidak berdaya', 'Mengatasi kebencian dengan kebaikan yang tulus sehingga dapat meluluhkan permusuhan dan menyadarkan hatinya yang keras', 'Memamerkan kekayaan makanan di depan musuh', 'Menjadikan musuh sebagai budak pengantar surat'], 1, 'Kebaikan yang diberikan kepada lawan meruntuhkan tembok permusuhan dan membuka pintu rekonsiliasi damai.');
addQ(5, 'sulit', 'Menyikapi Hasil Kerja Keras yang Gagal', 'Ketika Petrus dan kawan-kawannya semalam-malaman bekerja keras menjala ikan di danau namun tidak menangkap apa-apa, Yesus menyuruh bertolak ke tempat yang dalam. Ketaatan Petrus melahirkan ...', ['Perahu mereka karam diterjang badai', 'Tangkapan sejumlah besar ikan hingga jala mereka mulai koyak atas kuasa firman Kristus', 'Perselisihan antar nelayan di pantai', 'Kerugian modal membeli jala baru'], 1, 'Lukas 5:5: "Tetapi karena Engkau menyuruhnya, aku akan menebarkan jala juga." Ketaatan iman pada firman melahirkan mukjizat berkat melimpah.');
addQ(5, 'sulit', 'Kearifan Memilih Pergaulan Teman', '1 Korintus 15:33 mengingatkan: "Janganlah kamu sesat: Pergaulan yang buruk merusakkan ..."', ['Buku pelajaran sekolah', 'Kebiasaan yang baik', 'Sepatu olahraga yang baru', 'Jadwal jam tidur malam'], 1, 'Pengaruh lingkungan pergaulan yang salah secara perlahan dapat mengikis kebiasaan baik dan integritas moral anak muda.');
addQ(5, 'sulit', 'Etika Mengelola Marah Sesuai Mazmur 4', 'Mazmur 4:5 berpesan: "Biarlah kamu marah, tetapi jangan berbuat dosa; berkata-katalah dalam hatimu di tempat tidurmu, dan ..."', ['Menangislah sampai pagi menjelang', 'Berdiamlah', 'Pikirkankanlah rencana pembalasan dendam', 'Bantinglah bantal ke lantai'], 1, 'Mengheningkan batin dan berdiam di hadirat Tuhan saat marah mencegah luapan emosi destruktif yang melahirkan dosa.');
addQ(5, 'sulit', 'Menilai Kebenaran di Atas Tradisi Manusia', 'Yesus mengecam para ahli Taurat yang mengabaikan perintah Allah demi memelihara tradisi adat istiadat manusia (Matius 15:3). Pelajaran bagi kita adalah ...', ['Tradisi budaya selalu harus dihancurkan', 'Firman kebenaran Allah harus selalu menjadi otoritas tertinggi dan tolok ukur utama dalam menilai tradisi kebiasaan masyarakat', 'Semua manusia tidak boleh lagi menghormati orang tua', 'Hanya tradisi bangsa Romawi yang boleh diikuti'], 1, 'Otoritas firman Allah melampaui tradisi ciptaan manusia; tradisi yang bertentangan dengan keadilan dan kasih harus diperbarui.');
addQ(5, 'sulit', 'Makna "Bukan dengan Kekuatan, Bukan dengan Keperkasaan"', 'Zakharia 4:6 menegaskan: "Bukan dengan keperkasaan dan bukan dengan kekuatan, melainkan dengan ..."', ['Banyaknya tentara bayaran berkuda', 'Roh-Ku, firman TUHAN semesta alam', 'Kekayaan tambang emas di bukit', 'Ketajaman pedang perunggu'], 1, 'Pekerjaan rohani dan kemenangan iman sejati tidak dicapai oleh kehebatan otot materi manusia, melainkan oleh kuasa Roh Kudus.');
addQ(5, 'sulit', 'Analisis Pilihan Maria Duduk di Kaki Yesus', 'Mengapa tindakan Maria duduk bersimpuh mendengarkan firman di kaki Yesus pada zaman abad pertama dipandang sebagai tindakan yang sangat revolusioner?', ['Karena pada zaman kuno wanita dilarang duduk di lantai', 'Karena pada zaman itu wanita tidak diperbolehkan menjadi murid rabi untuk belajar Taurat, namun Yesus menyambut wanita sederajat dengan laki-laki sebagai murid kebenaran', 'Karena Maria sedang menderita sakit lutut', 'Supaya Maria tidak perlu memasak hidangan selamanya'], 1, 'Yesus mengangkat martabat wanita: mendobrak diskriminasi patriarkal dan membuka akses pengajaran ilahi yang setara bagi perempuan.');
addQ(5, 'sulit', 'Sikap Menghadapi Kekayaan Duniawi', '1 Timotius 6:10 memperingatkan: "Karena akar segala kejahatan ialah ..."', ['Uang kertas dan koin logam perak', 'Cinta uang; sebab oleh memburu uanglah beberapa orang telah menyimpang dari iman dan menyiksa dirinya dengan berbagai-bagai duka', 'Miskin harta di perkampungan kumuh', 'Bekerja keras setiap pagi'], 1, 'Bukan uangnya yang jahat, melainkan cinta uang (ketamakan hati) yang memperhamba nurani dan menjatuhkan manusia ke dalam kebinasaan.');
addQ(5, 'sulit', 'Teladan Daud Tidak Membalas Kutukan Simei', 'Ketika Daud melarikan diri dari kudeta Absalom dan disumpahi serta dilempari batu oleh Simei, Daud melarang pengawalnya memenggal kepala Simei dan berkata: "Biarkanlah dia mengutuk, sebab TUHAN yang menyuruh dia". Sikap Daud mencerminkan ...', ['Ketakutan Daud pada kekuatan Simei', 'Kerendahan hati penyerahan diri di bawah disiplin tangan Allah, menolak balas dendam pribadi dan mengharapkan belas kasihan Tuhan', 'Daud sedang terburu-buru mengejar kereta kuda', 'Daud tidak mendengar perkataan Simei'], 1, '2 Samuel 16: Daud menunjukkan kedewasaan iman: memandang di balik penghinaan musuh ada pembentukan karakter dari Tuhan.');
addQ(5, 'sulit', 'Menilai Integritas Tokoh Alkitab Nehemia', 'Ketika membangun kembali tembok Yerusalem di tengah ancaman musuh Sanbalat dan Tobia, Nehemia menolak melarikan diri ke dalam Bait Suci untuk bersembunyi dengan berkata: "Masakan orang seperti aku ini lari?". Karakter Nehemia adalah ...', ['Sombong dan merasa dirinya kebal senjata', 'Pemimpin yang berintegritas tinggi, berani, pantang menyerah, dan menaruh kehormatan iman di atas rasa takut akan bahaya', 'Mengabaikan keselamatan nyawa para pengawalnya', 'Ingin namanya diukir di gerbang tembok Yerusalem'], 1, 'Nehemia meneladankan integritas kepemimpinan rohani yang teguh berdiri di garis depan demi memulihkan bangsanya.');
addQ(5, 'sulit', 'Mutiara Kebajikan Yakobus Iman Tanpa Perbuatan', 'Yakobus 2:17 menegaskan: "Demikian juga halnya dengan iman: Jika iman itu tidak disertai perbuatan, maka iman itu pada hakikatnya adalah ..."', ['Mati', 'Akan bertumbuh sendiri setelah dewasa', 'Cukup untuk menyelamatkan seluruh keluarga', 'Paling disukai oleh para malaikat surga'], 1, 'Iman yang sejati bukan sekadar pengakuan verbal di bibir; iman yang hidup terbukti melalui perbuatan kasih nyata kepada sesama.');

addQ(6, 'mudah', 'Ibadah Sejati Roma 12', 'Berdasarkan Surat Roma 12:1, ibadah yang sejati dan berkenan kepada Allah adalah mempersembahkan ...', ['Hewan domba yang gemuk', 'Tubuh kita sebagai persembahan yang hidup, yang kudus, dan yang berkenan kepada Allah', 'Banyak emas permata ke dalam kotak persembahan', 'Pakaian pesta yang mewah'], 1, 'Ibadah sejati mencakup penyerahan seluruh hidup dan perilaku sehari-hari dalam kekudusan bagi Allah.');
addQ(6, 'mudah', 'Garam dan Terang Dunia', 'Dalam Khotbah di Bukit (Matius 5:13-14), Tuhan Yesus menyebut para murid-Nya sebagai garam dan ...', ['Bunga bakung di taman', 'Terang dunia', 'Batu karang di padang gurun', 'Pohon aras Libanon'], 1, 'Yesus memanggil umat-Nya menjadi garam yang memberi rasa dan mencegah kebusukan, serta terang yang menyinari kegelapan.');
addQ(6, 'mudah', 'Daniel di Gua Singa', 'Nabi Daniel dilemparkan ke dalam gua singa karena ia tetap setia ...', ['Mencuri roti raja Babel', 'Berdoa dan menyembah kepada Allah yang hidup tiga kali sehari', 'Merusak tembok kota Babel', 'Menolak membayar pajak emas'], 1, 'Daniel lebih taat kepada hukum Allah daripada undang-undang manusia yang melarang berdoa kepada Tuhan.');
addQ(6, 'mudah', 'Tiga Pemuda Api', 'Tiga pemuda Ibrani yang dicampakkan ke dalam perapian api yang menyala-nyala karena menolak menyembah patung emas adalah Sadrakh, Mesakh, dan ...', ['Abednego', 'Zerubabel', 'Nehemia', 'Mordekhai'], 0, 'Sadrakh, Mesakh, dan Abednego berdiri teguh mempertahankan iman tauhid mereka.');
addQ(6, 'mudah', 'Kitab Wahyu', 'Kitab terakhir dalam Alkitab yang memuat penglihatan Rasul Yohanes tentang Yerusalem baru dan kemenangan kekal Kristus adalah Kitab ...', ['Kejadian', 'Wahyu', 'Kisah Para Rasul', 'Ibrani'], 1, 'Kitab Wahyu (Apokalipsis) adalah kitab penutup Alkitab tentang pengharapan eskatologis jemaat.');
addQ(6, 'mudah', 'Semboyan Bangsa', 'Semboyan negara Indonesia yang mengajarkan kita untuk hidup rukun dan bersatu di tengah keberagaman suku dan agama adalah ...', ['Tut Wuri Handayani', 'Bhinneka Tunggal Ika', 'Ing Ngarso Sung Tulodo', 'Garuda Pancasila'], 1, 'Bhinneka Tunggal Ika berarti berbeda-beda tetapi tetap satu jua.');
addQ(6, 'mudah', 'Kesetaraan Martabat', 'Alkitab menegaskan bahwa di hadapan Allah seluruh manusia laki-laki dan perempuan memiliki martabat yang ...', ['Berbeda jauh kastanya', 'Sama dan setara sebagai ciptaan seturut gambar Allah', 'Ditentukan oleh banyaknya saldo tabungan bank', 'Hanya diakui bagi orang kaya'], 1, 'Galatia 3:28 menegaskan kesetaraan manusia di dalam Kristus Yesus tanpa sekat diskriminatif.');
addQ(6, 'mudah', 'Surat Pastoral Paulus', 'Surat-surat penggembalaan yang ditulis Rasul Paulus kepada murid-murid mudanya terabadikan dalam Kitab Timotius dan Kitab ...', ['Titus', 'Yudas', 'Nahum', 'Maleakhi'], 0, 'Surat 1-2 Timotius dan Titus adalah surat-surat pastoral bimbingan penggembalaan jemaat.');
addQ(6, 'mudah', 'Ayub yang Sabar', 'Tokoh Alkitab yang terkenal dengan kesabaran imannya yang luar biasa saat diuji dengan penderitaan berat adalah ...', ['Nabi Elia', 'Ayub', 'Nabi Yunus', 'Raja Ahab'], 1, 'Ayub dikenal sebagai teladan ketabahan iman di tengah kehilangan dan penderitaan.');
addQ(6, 'mudah', 'Hari Penghakiman', 'Alkitab mengajarkan bahwa pada akhir zaman Kristus akan datang kembali dalam kemuliaan untuk ...', ['Membangun kembali kota Babel', 'Menghakimi orang yang hidup dan yang mati dalam keadilan', 'Mengumpulkan koin-koin emas Romawi', 'Mengubah bumi menjadi planet es'], 1, 'Kedatangan Kristus kedua kali (Parousia) menyatakan pengadilan adil dan penggenapan Kerajaan Allah.');

addQ(6, 'sedang', 'Mulut Singa Terkatup', 'Nabi Daniel selamat tanpa luka sedikit pun di dalam gua singa yang lapar karena ...', ['Daniel membawa daging domba yang banyak', 'Allah mengutus malaikat-Nya untuk mengatupkan mulut singa-singa itu', 'Singa-singa tersebut sedang tertidur pulas', 'Daniel mahir ilmu bela diri gulat'], 1, 'Daniel 6:22: Allah melindungi Daniel yang tidak bersalah di hadapan-Nya dan di hadapan raja.');
addQ(6, 'sedang', 'Kaisar dan Allah', 'Yesus menjawab pertanyaan jebakan tentang membayar pajak dengan bersabda: "Berikanlah kepada Kaisar apa yang wajib kamu berikan kepada Kaisar dan kepada Allah apa yang ..."', ['Disukai oleh para prajurit', 'Wajib kamu berikan kepada Allah', 'Bisa disimpan di dalam lumbung', 'Berupa perak perunggu'], 1, 'Matius 22:21 mengajarkan tanggung jawab warga negara sekaligus kewajiban mutlak ketaatan kepada Allah.');
addQ(6, 'sedang', 'Menolak Narkoba Tubuh Kudus', 'Menjauhkan diri dari narkoba, minuman keras, dan pornografi di kalangan remaja merupakan bukti ketaatan pada firman bahwa tubuh kita adalah ...', ['Milik pribadi yang bebas dirusak', 'Bait Roh Kudus yang ditebus dengan darah yang mahal', 'Hanya mesin biologis tanpa jiwa', 'Titipan yang boleh diperjualbelikan'], 1, 'Tubuh orang percaya adalah kediaman Roh Kudus yang wajib dipelihara dalam kekudusan.');
addQ(6, 'sedang', 'Toleransi Indonesia', 'Sikap seorang pelajar kristiani dalam mendukung kerukunan umat beragama di lingkungan masyarakat adalah ...', ['Menolak bergaul dengan tetangga yang berbeda agama', 'Saling mengunjungi dalam silaturahmi sosial, menjaga ketertiban, dan tolong-menolong saat musibah', 'Membuat kebisingan saat umat lain beribadah', 'Memaksa kawan lain mengikuti ajaran agama kita'], 1, 'Kerukunan antarumat beragama dibangun di atas sikap saling menghormati dan solidaritas kemanusiaan.');
addQ(6, 'sedang', 'Pilatus Cuci Tangan', 'Tindakan gubernur Romawi Pontius Pilatus mencuci tangannya dengan air di depan orang banyak melambangkan ...', ['Upaya melepaskan diri dari tanggung jawab moral atas hukuman mati Yesus yang tidak bersalah', 'Kebersihan diri sebelum makan siang', 'Penyucian diri dari debu padang pasir', 'Perayaan hari raya Paskah Yahudi'], 0, 'Pilatus mencuci tangan sebagai simbol cuci tangan moral, namun ia tetap bersalah membiarkan ketidakadilan terjadi.');
addQ(6, 'sedang', 'Simon Kirene', 'Pria dari Kirene yang dipaksa oleh tentara Romawi untuk membantu memikul salib Yesus menuju bukit Golgota bernama ...', ['Simon Petrus', 'Simon dari Kirene', 'Simon orang Zelot', 'Simon sang penyihir'], 1, 'Matius 27:32: Simon dari Kirene memikul kayu salib Kristus di jalan penderitaan (Via Dolorosa).');
addQ(6, 'sedang', 'Bukit Golgota', 'Tempat penyaliban Tuhan Yesus Kristus berada di luar pintu gerbang kota Yerusalem di sebuah bukit bernama Golgota, yang artinya ...', ['Bukit Kemenangan Raja', 'Tempat Tengkorak', 'Lembah Bunga Bakung', 'Gunung Kemerdekaan'], 1, 'Golgota berasal dari bahasa Aram yang berarti Tempat Tengkorak (Calvaria dalam bahasa Latin).');
addQ(6, 'sedang', 'Tirai Bait Suci Terbelah', 'Ketika Yesus menyerahkan nyawa-Nya di salib, tirai penutup Ruang Mahakudus di Bait Suci terbelah dua dari atas ke bawah, yang menandakan ...', ['Bait Suci mengalami kerusakan fisik akibat gempa saja', 'Terbukanya jalan masuk langsung bagi setiap orang beriman menghadap hadirat Allah tanpa perantara imam manusiawi lagi', 'Tirai kain tersebut sudah lapuk dimakan ngengat', 'Larangan bagi orang banyak masuk ke gereja'], 1, 'Matius 27:51: Kematian Kristus meruntuhkan sekat pemisah, membuka akses langsung ke hadirat takhta anugerah Allah.');
addQ(6, 'sedang', 'Pengakuan Perwira Romawi', 'Perwira Romawi yang memimpin regu prajurit penjaga salib di Golgota, setelah melihat bagaimana Yesus wafat dan peristiwa alam yang terjadi, berseru: ...', ['"Orang ini pantas dihukum mati!"', '"Sungguh, Orang ini adalah Anak Allah!"', '"Bawakan air minum untuk prajurit!"', '"Mari kita segera pulang ke markas Roma!"'], 1, 'Matius 27:54: Pengakuan iman yang luar biasa dari seorang perwira kafir Romawi.');
addQ(6, 'sedang', 'Makam Yusuf Arimatea', 'Jenazah Yesus diturunkan dari salib dan dimakamkan dengan penuh hormat di dalam kubur batu baru milik seorang anggota majelis agama yang saleh bernama ...', ['Nikodemus', 'Yusuf dari Arimatea', 'Gamaliel', 'Kayafas'], 1, 'Yusuf dari Arimatea dengan berani menghadap Pilatus untuk meminta jenazah Yesus dimakamkan secara layak.');
addQ(6, 'sedang', 'Seruan Nabi Amos Keadilan', 'Nabi Amos yang membela kaum miskin menyerukan firman TUHAN: "Tetapi biarlah keadilan bergulung-gulung seperti air dan kebenaran seperti ..."', ['Batu karang yang kokoh di padang', 'Sungai yang selalu mengalir', 'Api yang membakar jerami kering', 'Hujan es di musim panas'], 1, 'Amos 5:24 menuntut keadilan sosial dan integritas moral yang terus mengalir dalam kehidupan bangsa.');
addQ(6, 'sedang', 'Tujuan Menjadi Terang', 'Tujuan orang percaya melakukan perbuatan baik sebagai terang dunia menurut Matius 5:16 adalah agar orang-orang ...', ['Memberi kita hadiah piala kejujuran', 'Melihat perbuatan baikmu dan memuliakan Bapamu yang di surga', 'Memilih kita menjadi bupati atau walikota', 'Takut dan tunduk kepada kita'], 1, 'Perbuatan baik orang beriman bukan untuk mencari kemuliaan diri sendiri, melainkan agar Bapa di surga dimuliakan.');
addQ(6, 'sedang', 'HAM dan Gambar Allah', 'Penghormatan terhadap Hak Asasi Manusia (HAM) dalam perspektif iman kristiani berakar kokoh pada pengakuan bahwa setiap manusia ...', ['Memiliki kekayaan materi yang berlimpah', 'Diciptakan mulia menurut gambar dan rupa Allah (Imago Dei)', 'Berasal dari suku bangsa pemenang perang', 'Pernah bersekolah di sekolah favorit'], 1, 'Martabat luhur manusia tidak bersumber dari status sosial, melainkan dari anugerah penciptaan Ilahi.');
addQ(6, 'sedang', 'Upacara Bendera Nasionalisme', 'Mengikuti upacara bendera hari Senin di halaman sekolah dengan khidmat merupakan wujud ...', ['Membuang-buang waktu jam belajar', 'Kecintaan kepada tanah air dan penghormatan kepada para pahlawan bangsa', 'Kewajiban terpaksa agar tidak dihukum push-up', 'Pamer seragam baru'], 1, 'Nasionalisme yang sehat adalah bagian dari tanggung jawab orang percaya mengusahakan kesejahteraan kota dan bangsa.');
addQ(6, 'sedang', 'Ucapan Iman Ayub', 'Ketika tertimpa musibah kehilangan seluruh harta kekayaan dan anak-anaknya dalam satu hari, Ayub sujud dan berkata: ...', ['"Tuhan tidak adil kepadaku!"', '"TUHAN yang memberi, TUHAN yang mengambil, terpujilah nama TUHAN!"', '"Aku akan mengutuk hari kelahiranku!"', '"Semua ini salah para pelayan yang ceroboh!"'], 1, 'Ayub 1:21: Pernyataan iman puncak yang mengakui kedaulatan mutlak Allah atas kepemilikan hidup.');
addQ(6, 'sedang', 'Kesaksian Akhir Paulus', 'Menjelang akhir hayatnya di Roma, Rasul Paulus menulis kepada Timotius: "Aku telah mengakhiri pertandingan yang baik, aku telah mencapai garis akhir dan aku telah memelihara ..."', ['Harta kekayaanku', 'Iman', 'Kesehatan fisikku', 'Pasukan berkudaku'], 1, '2 Timotius 4:7: Kesaksian kemenangan iman seorang rasul yang setia melayani sampai akhir hayat.');
addQ(6, 'sedang', 'Persatuan Sila Ketiga', 'Kerukunan hidup antarwarga bangsa tanpa membeda-bedakan latar belakang agama mendukung terwujudnya sila ke-3 Pancasila yaitu ...', ['Ketuhanan Yang Maha Esa', 'Persatuan Indonesia', 'Keadilan Sosial', 'Kemanusiaan yang Adil dan Beradab'], 1, 'Sila ke-3 Persatuan Indonesia menuntut seluruh elemen bangsa memelihara keutuhan NKRI.');
addQ(6, 'sedang', 'Etika Musyawarah Kelas', 'Ketika kelas mengadakan musyawarah untuk menentukan tujuan karya wisata, sikap murid yang demokratis dan kristiani adalah ...', ['Memaksakan pilihannya sendiri dan mengancam keluar kelompok', 'Menyampaikan usulan dengan santun, menghargai pendapat orang lain, dan menerima mufakat bersama', 'Mengejek pendapat teman yang berbeda', 'Diam saja lalu menggerutu di belakang'], 1, 'Musyawarah yang dilandasi kerendahan hati dan saling menghargai menghasilkan damai dan mufakat berkah.');
addQ(6, 'sedang', 'Doa Kelulusan Pelajar', 'Menjelang kelulusan sekolah dasar dan melangkah ke SMP, doa permohonan utama seorang murid kristiani adalah ...', ['Memohon kekayaan instan tanpa perlu belajar lagi', 'Memohon hikmat, bimbingan Tuhan agar terus hidup kudus, berkarakter mulia, dan berprestasi demi kemuliaan Allah', 'Supaya tidak ada lagi tugas rumah di sekolah baru', 'Agar semua ujian bisa diselesaikan dengan menebak jawaban'], 1, 'Memohon pimpinan Tuhan untuk melangkah ke jenjang pendidikan berikutnya dengan hikmat dan integritas.');
addQ(6, 'sedang', 'Pesan Penutup Matius Amanat Agung', 'Sebelum naik ke surga, Yesus memberikan Amanat Agung dalam Matius 28:19: "Karena itu pergilah, jadikanlah semua bangsa ..."', ['Takluk di bawah kekuatan senjata', 'Murid-Ku dan baptislah mereka dalam nama Bapa dan Anak dan Roh Kudus', 'Pelayan upahan di bait suci', 'Pedagang kaya di Yerusalem'], 1, 'Amanat Agung adalah tugas perutusan gereja memuridkan segala bangsa dalam kasih dan kebenaran Kristus.');

addQ(6, 'sulit', 'Analisis Teologis Garam Dunia', 'Yesus bersabda: "Kamu adalah garam dunia. Jika garam itu menjadi tawar, dengan apakah ia diasinkan? Tidak ada lagi gunanya selain dibuang dan diinjak orang". Peringatan keras ini ditujukan kepada orang percaya yang ...', ['Tidak suka memasak makanan di dapur', 'Kehilangan integritas moral, berkompromi dengan kejahatan dunia, dan tidak lagi memberi dampak pembaruan bagi lingkungannya', 'Lupa membawa garam saat bepergian ke luar kota', 'Menjual garam dengan harga murah'], 1, 'Orang beriman yang kehilangan identitas kekudusan dan rasa keadilan Kristus menjadi tidak berguna bagi kesaksian Kerajaan Allah.');
addQ(6, 'sulit', 'Dilema Moral Integritas Daniel', 'Ketika para menteri licik menjebak Daniel dengan undang-undang yang melarang berdoa kepada siapa pun selain raja Darius selama 30 hari, mengapa Daniel tidak memilih berdoa diam-diam di dalam lemari gelap?', ['Karena Daniel ingin sengaja menantang raja berperang', 'Karena Daniel tidak mau mengorbankan integritas kesaksian imannya kepada Allah; ia membuka tingkap kamarnya yang menghadap Yerusalem dan berdoa dengan tenang seperti yang biasa dilakukannya', 'Karena Daniel tidak tahu adanya undang-undang tersebut', 'Supaya singa-singa di gua diberi makan'], 1, 'Daniel 6:10: Daniel menolak kompromi kepengecutan rohani; integritas ibadah kepada Allah ditegakkannya secara konsisten tanpa takut ancaman maut.');
addQ(6, 'sulit', 'Kritik Nabi Amos Terhadap Kemunafikan Ibadah', 'Dalam Amos 5:21-23, TUHAN berfirman: "Aku membenci, Aku menghinakan perayaanmu... jauhkanlah dari pada-Ku keramaian nyanyian-nyanyianmu". Mengapa ibadah bangsa Israel dibenci oleh Allah?', ['Karena suara paduan suara mereka fals dan tidak merdu', 'Karena ibadah ritual mereka yang meriah tidak disertai dengan perbuatan adil, mereka memeras kaum miskin dan menindas orang lemah di pengadilan gerbang kota', 'Karena mereka lupa menyalakan lilin mezbah', 'Karena korban bakaran mereka terbakar hangus'], 1, 'Ibadah ritual tanpa penegakan keadilan sosial dan belas kasih bagi kaum tertindas adalah kekejian di hadapan Allah yang Mahasuci.');
addQ(6, 'sulit', 'Makna Tirai Terbelah Dua Akses Anugerah', 'Penulis Surat Ibrani 10:19-20 menjelaskan bahwa melalui tirai yang terbelah (yaitu tubuh Kristus), orang percaya sekarang memiliki ...', ['Izin untuk menghancurkan Bait Allah di Yerusalem', 'Keberanian untuk masuk ke dalam Tempat Kudus Allah oleh darah Yesus melalui jalan yang baru dan hidup', 'Kewajiban mempersembahkan korban darah binatang setiap tahun', 'Hak untuk tidak perlu berdoa lagi'], 1, 'Karya salib Kristus menghapus perantara imamat lama dan menganugerahkan akses langsung ke hadirat takhta anugerah Bapa.');
addQ(6, 'sulit', 'Pembaruan Budi Roma 12:2', 'Roma 12:2 menyatakan: "Janganlah kamu menjadi serupa dengan dunia ini, tetapi berubahlah oleh pembaruan budimu...". Bagaimana penerapan ayat ini bagi remaja kristiani menghadapi tekanan tren negatif di media sosial?', ['Menghindari menggunakan listrik dan komputer', 'Tidak ikut-ikutan meniru gaya hidup hedonis, vulgar, atau pergaulan bebas yang dianggap wajar oleh dunia, melainkan menyaringnya dengan nilai-nilai firman Allah', 'Menyendiri dan mengurung diri di dalam rumah', 'Memaki semua pembuat konten yang sedang viral'], 1, 'Transformasi akal budi menuntun orang percaya memiliki daya kritis rohani untuk membedakan mana kehendak Allah: apa yang baik, yang berkenan, dan yang sempurna.');
addQ(6, 'sulit', 'Analisis Keteguhan Tiga Pemuda "Tetapi Seandainya Tidak"', 'Ketika Sadrakh, Mesakh, dan Abednego berkata: "Allah kami sanggup melepaskan kami... tetapi seandainya tidak, kami tetap tidak akan menyembah dewa tuanku", pelajaran iman terdalam yang mereka teladankan adalah ...', ['Mereka yakin memiliki jimat penangkal api yang sakti', 'Iman yang sejati tidak berlandaskan barter keuntungan atau kepastian mukjizat fisik, melainkan ketaatan cinta yang mutlak kepada Allah sekalipun harus mati sebagai martir', 'Mereka berharap raja Nebukadnezar akan berbelas kasihan', 'Mereka mengira api perapian itu hanyalah ilusi mata'], 1, 'Iman "seandainya tidak" (even if not) adalah mahakarya keteguhan iman yang tidak menuntut syarat pemeliharaan fisik semata.');
addQ(6, 'sulit', 'Tantangan Menjadi Terang di Era Cyberbullying', 'Ketika terjadi perundungan massal (cyberbullying) di grup obrolan media sosial terhadap seorang teman yang lemah, tindakan "anak terang" adalah ...', ['Ikut mengirimkan stiker mengejek agar dianggap humoris oleh geng kelas', 'Berani bersuara menghentikan perundungan tersebut, membela korban secara empat mata, dan melaporkannya kepada guru pembimbing jika keterlaluan', 'Menghapus aplikasi WhatsApp dan pura-pura tidak tahu', 'Membuat akun anonim untuk membalas memaki pelaku'], 1, 'Anak terang menolak bersekutu dengan kegelapan penindasan; berani berdiri tegak menyuarakan kebenaran dan pembelaan bagi yang tertindas.');
addQ(6, 'sulit', 'Kearifan Bernegara Memberi Kepada Kaisar dan Allah', 'Bagaimana orang percaya menyeimbangkan kewajibannya kepada negara (pemerintah) dan kepada Allah dalam kehidupan bermasyarakat?', ['Hanya patuh kepada undang-undang jika dipimpin oleh orang seagama', 'Taat dan tunduk kepada hukum negara yang adil, membayar pajak, dan menjaga ketertiban umum, namun kesetiaan tertinggi hati nurani tetap tak tergoyahkan kepada hukum Allah', 'Menolak mematuhi peraturan lalu lintas karena bukan hukum Alkitab', 'Mengabaikan seluruh urusan kenegaraan'], 1, 'Orang kristiani dipanggil menjadi warga negara yang teladan dalam hukum duniawi tanpa pernah mengorbankan kesetiaan iman mutlak kepada Allah.');
addQ(6, 'sulit', 'Analisis Nubuat Yerikho Baru Wahyu 21', 'Dalam Kitab Wahyu 21:3-4 digambarkan langit dan bumi yang baru di mana Allah akan diam bersama manusia dan "Ia akan menghapus segala air mata dari mata mereka, dan ..."', ['Maut tidak akan ada lagi; tidak akan ada lagi perkabungan, atau ratap tangis, atau dukacita', 'Bumi akan dipenuhi jalan raya dari emas batangan murni', 'Manusia tidak perlu lagi bekerja sama sekali', 'Matahari akan bersinar seribu kali lebih panas'], 0, 'Pengharapan eskatologis puncak kekristenan adalah pemulihan kosmis sempurna di mana dosa, penderitaan, dan maut dihapuskan selamanya.');
addQ(6, 'sulit', 'Keteladanan Stefanus Mengubah Saulus', 'Banyak bapa gereja menyatakan bahwa doa Stefanus yang penuh kasih saat dilempari batu ("Tuhan jangan tanggungkan dosa ini...") menjadi benih spiritual yang melunakkan hati seorang saksi muda yang menjaga jubah para pelempar batu, yaitu ...', ['Kaisar Agustus', 'Saulus dari Tarsus (kemudian menjadi Rasul Paulus)', 'Gubernur Feliks', 'Raja Agripa'], 1, 'Kisah Para Rasul 7:58: Saulus menyaksikan langsung kematian mulia dan doa pengampunan Stefanus yang mengguncang nuraninya.');
addQ(6, 'sulit', 'Perlawanan Terhadap Rasisme Galatia 3:28', 'Rasul Paulus menyatakan: "Dalam hal ini tidak ada orang Yahudi atau orang Yunani, tidak ada hamba atau orang merdeka, tidak ada laki-laki atau perempuan, karena kamu semua adalah ..."', ['Keturunan para bangsawan Romawi', 'Satu di dalam Kristus Yesus', 'Warga negara imperium yang merdeka', 'Ahli filsafat Yunani kuno'], 1, 'Injil meruntuhkan dinding pemisah rasial, kasta sosial, dan ketidaksetaraan gender di dalam kesatuan tubuh Kristus.');
addQ(6, 'sulit', 'Tantangan Menghadapi Paham Radikalisme Agama', 'Bagaimana ajaran Yesus tentang "mengasihi musuh dan memberkati orang yang mengutuk kamu" menjadi penawar ampuh membendung racun fanatisme radikal dan terorisme?', ['Dengan melarang orang beribadah di gereja', 'Dengan mengganti dendam kebencian kekerasan dengan kekuatan kasih pemulihan, dialog kemanusiaan, dan pemutusan rantai balas dendam', 'Dengan membalas membakar tempat ibadah lawan', 'Dengan melarikan diri ke luar negeri'], 1, 'Kasih Kristus menolak kekerasan berdarah; ia mematahkan spiral dendam dengan kurban kasih yang menyelamatkan.');
addQ(6, 'sulit', 'Menilai Dilema Moral Sahabat Yonatan dan Daud', 'Ketika Yonatan berada di antara kesetiaan kepada ayahnya Raja Saul yang semakin gila kekuasaan dan kesetiaan kepada Daud yang diurapi Tuhan, prinsip moral yang dipilih Yonatan adalah ...', ['Membantu ayahnya membunuh Daud demi warisan takhta kerajaan', 'Memilih kebenaran dan keadilan Allah dengan membela Daud yang tidak bersalah, sembari tetap menghormati ayahnya hingga gugur bersama di medan perang', 'Meracuni ayahnya sendiri di istana', 'Melarikan diri ke tanah Mesir'], 1, 'Yonatan meneladankan integritas ksatria sejati: berdiri di pihak kebenaran Allah tanpa menciderai bakti kasih persaudaraan.');
addQ(6, 'sulit', 'Makna "Bukan untuk Dilayani Melainkan Melayani"', 'Markus 10:45 mencatat perkataan Yesus: "Karena Anak Manusia juga datang bukan untuk dilayani, melainkan untuk melayani dan untuk memberikan nyawa-Nya menjadi ..."', ['Tebusan bagi banyak orang', 'Upah bagi para prajurit bait suci', 'Kekayaan bagi murid-murid-Nya', 'Raja di istana kaisar Roma'], 0, 'Hakikat terdalam misi inkarnasi Kristus adalah pelayanan pengorbanan diri sebagai tebusan dosa bagi keselamatan umat manusia.');
addQ(6, 'sulit', 'Analisis Sikap Pria Kaya yang Sukar Masuk Surga', 'Mengapa orang muda kaya yang taat hukum Taurat sejak kecil akhirnya pergi dengan sedih setelah berbicara dengan Yesus?', ['Karena Yesus memintanya berjalan kaki ke Mesir', 'Karena Yesus memintanya menjual seluruh hartanya, membagikannya kepada orang miskin, dan mengikut Dia; hatinya terikat erat dan diperhamba oleh kekayaannya melebihi ketaatannya kepada Allah', 'Karena Yesus melarangnya pulang ke rumah orang tuanya', 'Karena ia kalah berdebat dengan para rasul'], 1, 'Matius 19:22: Berhala kekayaan materi menjadi batu sandungan yang membelenggu hatinya dari penyerahan diri total kepada Kristus.');
addQ(6, 'sulit', 'Integritas Penatalayanan Waktu Siswa Berprestasi', 'Bagaimana seorang siswa kelas 6 kristiani menata kehidupannya saat menghadapi persiapan ujian sekolah sekaligus tugas pelayanan di gereja?', ['Meninggalkan seluruh jam ibadah gereja selama satu tahun penuh', 'Mengatur jadwal belajar dan pelayanan secara disiplin, memohon hikmat Tuhan, dan tidak menyia-nyiakan waktu untuk hal-hal yang sia-sia', 'Menyontek saat ujian agar waktu belajarnya bisa dipakai main game', 'Meminta dispensasi kelulusan tanpa perlu mengikuti ujian'], 1, 'Manajemen waktu yang bijaksana mencerminkan karakter penatalayan yang setia atas waktu yang dianugerahkan Tuhan.');
addQ(6, 'sulit', 'Tantangan Menghadapi Diskriminasi di Sekolah', 'Bila di sekolah umum seorang murid kristiani menjadi minoritas dan sering dipojokkan dalam diskusi, sikap keteladanan yang diajarkan Rasul Petrus adalah ...', ['Membalas memaki dengan kata-kata kotor di media sosial', 'Selalu siap memberi pertanggungjawaban tentang pengharapan iman dengan lemah lembut dan hormat, serta memelihara hati nurani yang murni', 'Mogok tidak mau masuk sekolah selamanya', 'Menyembunyikan identitas agamanya karena malu'], 1, '1 Petrus 3:15-16 menasihatkan menjawab pertanyaan iman dengan kelemahlembutan, rasa hormat, dan nurani yang murni.');
addQ(6, 'sulit', 'Makna Kebangkitan Kristus Mengalahkan Maut', 'Dalam 1 Korintus 15:55-57, Rasul Paulus berseru dengan sorak kemenangan: "Hai maut di manakah kemenanganmu? Hai maut, di manakah sengatmu?... Tetapi syukur kepada Allah, yang telah memberikan kepada kita kemenangan oleh ..."', ['Kekuatan armada perang Romawi', 'Yesus Kristus, Tuhan kita', 'Kecerdasan akal budi manusia', 'Banyaknya korban persembahan lembu'], 1, 'Kebangkitan Kristus mematahkan kuasa sengat maut dan memberikan pengharapan hidup kekal yang pasti bagi orang percaya.');
addQ(6, 'sulit', 'Kearifan Menghadapi Perbedaan Aliran Gereja', 'Di Indonesia terdapat berbagai denominasi gereja (seperti Protestan, Pentakosta, Karismatik, dsb). Sikap ekumenis yang benar dalam terang firman Tuhan adalah ...', ['Saling menganggap gerejanya sendiri yang paling benar dan menuduh gereja lain sesat', 'Mengakui satu Tuhan, satu iman, dan satu baptisan dalam Kristus, serta bekerja sama dalam kasih persaudaraan memajukan kabar baik Kerajaan Allah', 'Memaksa semua gereja memakai liturgi yang sama persis', 'Menolak menghadiri persekutuan doa bersama'], 1, 'Efesus 4:5: Semangat ekumenis memelihara kesatuan roh oleh ikatan damai sejahtera di bawah satu Tuhan Kristus.');
addQ(6, 'sulit', 'Penatalayanan Ekologis Era Pemanasan Global', 'Bagaimana murid kristiani kelas 6 mengamalkan tanggung jawab iman menghadapi krisis perubahan iklim global?', ['Menganggap krisis iklim tidak penting karena dunia pasti akan kiamat', 'Mempraktikkan gaya hidup hemat energi, mengurangi penggunaan plastik sekali pakai, menanam pohon, dan merawat kelestarian lingkungan hidup kepunyaan Tuhan', 'Menghabiskan air bersih setiap kali mencuci sepeda', 'Membakar sampah plastik di halaman belakang'], 1, 'Merawat bumi adalah mandat etis penatalayanan iman bagi generasi kini dan masa depan.');
addQ(6, 'sulit', 'Analisis Kematangan Karakter Buah Roh', 'Galatia 5:23 menyatakan bahwa terhadap buah-buah Roh "tidak ada hukum yang menentang". Mengapa hukum Taurat atau hukum negara tidak menentang orang yang hidup berbuah Roh?', ['Karena orang berbuah Roh tidak perlu membayar pajak', 'Karena buah Roh (kasih, kebaikan, damai, penguasaan diri) melampaui dan menggenapi standar moral tertinggi yang justru dirindukan oleh setiap sistem hukum yang adil', 'Karena buah Roh hanya berlaku di dalam gedung gereja', 'Hanya metafora bahasa sastra'], 1, 'Karakter buah Roh menghasilkan kehidupan yang bebas dari celaan hukum karena memancarkan keadilan dan kasih sempurna.');
addQ(6, 'sulit', 'Menilai Ujian Kesabaran Ayub dari Sahabat-sahabatnya', 'Ketika sahabat-sahabat Ayub (Elifas, Bildad, dan Zofar) datang menghibur namun kemudian justru menuduh Ayub pasti telah berbuat dosa tersembunyi hingga diazab Allah, kesalahan teologis terbesar sahabat Ayub adalah ...', ['Mereka lupa membawa makanan ke rumah Ayub', 'Mereka membatasi cara kerja Allah semata-mata pada hukum karma pembalasan mekanis dan menghakimi orang yang sedang menderita tanpa belas kasihan', 'Mereka berbicara dengan bahasa asing yang tidak dimengerti Ayub', 'Mereka menolak berbicara selama tujuh hari'], 1, 'Sahabat Ayub terjebak teologi pembalasan sempit dan gagal menunjukkan empati kasih bagi penderitaan orang yang benar.');
addQ(6, 'sulit', 'Kekuatan Doa Yesus di Taman Getsemani', 'Dalam pergumulan batin yang dahsyat di Taman Getsemani menjelang salib, Yesus berdoa: "Ya Bapa-Ku, jikalau cawan ini tidak dapat lalu... jadilah kehendak-Mu!". Keteladanan agung Yesus dalam doa ini adalah ...', ['Menyerah pasrah tanpa perlawanan', 'Ketundukan dan ketaatan mutlak kepada rencana penebusan Bapa di atas keinginan kemanusiaan diri-Nya sendiri', 'Yesus tidak tahu apa yang akan terjadi di Golgota', 'Yesus meminta para murid bertarung dengan pedang'], 1, 'Matius 26:42: Doa Getsemani adalah puncak penyerahan ketaatan penuh Kristus menuntaskan rencana keselamatan Allah bagi manusia.');
addQ(6, 'sulit', 'Menghadapi Era Hedonisme Materialistik', 'Lukas 12:15 memperingatkan: "Berjaga-jagalah dan waspadalah terhadap segala ketamakan, sebab walaupun seorang berlimpah-limpah hartanya, hidupnya tidaklah tergantung dari pada ..."', ['Kekayaannya', 'Kesehatannya', 'Nama baik keluarganya', 'Buku-buku pengetahuannya'], 0, 'Nilai dan keselamatan hidup manusia sejati tidak ditentukan oleh kelimpahan kepemilikan materi fana.');
addQ(6, 'sulit', 'Karakter Pemimpin Pelayan (Servant Leadership)', 'Dalam Markus 10:43-44 Yesus menetapkan pola kepemimpinan Kerajaan Allah: "Barangsiapa ingin menjadi besar di antara kamu, hendaklah ia menjadi pelayanmu, dan barangsiapa ingin menjadi yang terkemuka di antara kamu, hendaklah ia menjadi ..."', ['Jenderal perang yang ditakuti', 'Hamba untuk semuanya', 'Saudagar paling kaya di pasar', 'Hakim yang keras menghukum'], 1, 'Kemuliaan kepemimpinan kristiani diukur dari kerendahan hati melayani dan memberdayakan sesama dengan kasih.');
addQ(6, 'sulit', 'Pemberian Terbesar Seorang Martir Zaman Modern', 'Kisah Pendeta Dietrich Bonhoeffer yang berani menentang kekejaman rezim Nazi Hitler demi membela orang Yahudi hingga dihukum mati mengajarkan bahwa kemuridan kristiani sejati adalah ...', ['Mencari keselamatan diri sendiri yang aman dan nyaman', 'Anugerah yang mahal (costly grace) yang menuntut keberanian membela keadilan dan kebenaran apa pun taruhan nyawanya', 'Membela kepentingan politik kelompok sendiri', 'Menolak berbicara tentang urusan masyarakat'], 1, 'Bonhoeffer meneladankan konsep "costly grace": anugerah keselamatan menuntut komitmen etis membela martabat kemanusiaan.');
addQ(6, 'sulit', 'Analisis Doa Penyaliban Bagi Musuh', 'Ketika Yesus disalibkan dan berdoa bagi para prajurit yang menyiksa-Nya, kuasa pengampunan dari atas kayu salib membuktikan bahwa ...', ['Yesus tidak merasakan sakit pada paku salib', 'Kasih pengampunan Allah lebih kuat daripada kedahsyatan kebencian dan kejahatan manusia yang paling brutal sekalipun', 'Para prajurit Romawi adalah murid tersembunyi Yesus', 'Salib adalah hukuman yang salah alamat'], 1, 'Salib adalah panggung kemenangan kasih yang melucuti kuasa kebencian dan menawarkan pengampunan bagi orang berdosa.');
addQ(6, 'sulit', 'Tantangan Menjaga Kemurnian Doktrin dan Kasih', 'Dalam Wahyu 2:4, Tuhan memuji jemaat Efesus yang gigih menguji rasul palsu, namun menegur mereka karena: "Engkau telah meninggalkan ..."', ['Gedung gereja lamamu', 'Kasihmu yang semula', 'Kotak uang persembahanmu', 'Alat musik kecapimu'], 1, 'Kebenaran doktrinal tanpa kasih adalah kematian rohani; ortodoksi harus selalu berpadu dengan kehangatan kasih Kristus yang menyala.');
addQ(6, 'sulit', 'Etika Pertanggungjawaban Akhir Zaman', '2 Korintus 5:10 mengingatkan: "Sebab kita semua harus menghadap takhta pengadilan Kristus, supaya setiap orang memperoleh apa yang patut diterimanya, sesuai dengan ..."', ['Banyaknya pujian yang didapat di media sosial', 'Apa yang dilakukannya dalam hidupnya ini, baik ataupun jahat', 'Gelar pendidikan akademis yang diraihnya', 'Kekayaan warisan leluhurnya'], 1, 'Kesadaran eskatologis akan penghakiman Kristus melahirkan pertanggungjawaban etis untuk senantiasa hidup berkenan kepada-Nya.');
addQ(6, 'sulit', 'Penyerahan Hidup Menuju Masa Depan', 'Yeremia 29:11 menyatakan janji Allah bagi umat-Nya yang setia: "Sebab Aku ini mengetahui rancangan-rancangan apa yang ada pada-Ku mengenai kamu, demikianlah firman TUHAN, yaitu rancangan ..."', ['Kecelakaan dan malapetaka di padang gurun', 'Damai sejahtera dan bukan rancangan kecelakaan, untuk memberikan kepadamu hari depan yang penuh harapan', 'Kekayaan emas tanpa perlu berusaha', 'Kehancuran bangsa-bangsa tetangga'], 1, 'Janji Allah meneguhkan iman generasi muda melangkah menyongsong masa depan dengan damai sejahtera dan pengharapan yang teguh.');

